result.text:
.acc-warn strong { display: block; margin-bottom: 3px; }
.acc-warn .btn { margin-top: 9px; }

@media (max-width: 620px) {
  .acc-tabs { gap: 5px; }
  .acc-tab { padding: 5px 10px; font-size: 12px; }
  .acc-table .acc-label { white-space: normal; }
  .acc-warn { font-size: 12.5px; }
  .acc-toolbar-note { flex-wrap: wrap; }
  .acc-toolbar-note .btn { margin-left: 0; }
}

/* Sello de versión en la barra lateral: sirve para saber de un vistazo si el
   navegador está enseñando los ficheros nuevos o una copia vieja guardada. */
.foot-version {
  margin: 7px 0 0;
  font-size: 11px;
  line-height: 1.3;
  letter-spacing: 0.02em;
  opacity: 0.72;
}
